[617]="藤萝垂碧栅，鹿儿啮红莓，深林涵和气，万物自驯良。",
[618]=" 翠林苑·小",
[619]="陨铁锢深林，虎君啸霜月，狂魂困阵纹，野性慑星斗。",
[620]=" 翠林苑·大",
[621]="玉栏锁烟岚，雏鸾振初羽，乘风探琼霄，犹怯九天寒。",
[622]="云霭苑·小",
