[627]="霜刃列森然，白狰伏冰狱，忠骨淬玄冰，凛冽铸丹心。",
[628]="霜晶苑·大",
[629]="藤络栖云榻，香凝碧玉觞。拈花惊蝶梦，原是彩衣藏。",
[630]="芳菲苑·小",
[631]="绯霞碧落缀瑶台，桃夭灼灼抱春怀。东君醉泼胭脂雨，香阵扶摇上九垓。",
[632]="芳菲苑·大",
[633]="风漩吞落日，驼影拱孤台。忽见青旌动，方知蜃气开。",
[634]="瀚沙苑·小",
[635]="驼铃碎月埋荒碛，白骨盘沙筑巨隍。千帐风摇星作雨，孤烟直上破玄苍。",
[636]="瀚沙苑·大",
[637]="炎精淬玄铁，罡风塑嶙峋。拾得祝融烬，可铸不老针。",
[638]="熔石苑·小",
[639]="地火焚霄裂玄穹，虬龙吐焰煅天工。万古熔岩凝铁骨，桀石参差刺碧空。",
[640]="熔石苑·大",
[641]="火云织霓锦，炎池淬金晶。历焰见真意，一照彻幽冥。",
[642]="蟠龙苑·小",
[643]="赤浪焚空煮八溟，炎龙盘柱镇乾坤。玄甲耀金熔地脉，神威直欲夺天焚。",
[644]="蟠龙苑·大",
[645]="波光摇翠幌，贝阙隐鲛纱。拾得鲛人泪，夜夜泛仙槎。",
[646]="沧渊苑·小",
[647]="鲛珠泪凝碧琉璃，寒蕖幽绽月华滋。星斗倒悬探龙府，珊瑚玉树海心峙。",
